define("tiny_omeroembed/commands", ["exports", "editor_tiny/utils", "tiny_omeroembed/ui", "core/str", "tiny_omeroembed/common"], function(exports, Utils, Ui, Str, Common) {
    "use strict";
    Object.defineProperty(exports, "__esModule", {value: true});

    exports.getSetup = function() {
        return Promise.all([
            Str.getString("buttontitle", Common.component),
            Utils.getButtonImage("icon", Common.component),
        ]).then(function(results) {
            var buttonText = results[0];
            var buttonImage = results[1];

            return function(editor) {
                editor.ui.registry.addIcon(Common.icon, buttonImage.html);

                editor.ui.registry.addButton(Common.buttonName, {
                    icon: Common.icon,
                    tooltip: buttonText,
                    onAction: function() {
                        Ui.handleAction(editor);
                    },
                });

                editor.ui.registry.addMenuItem(Common.buttonName, {
                    icon: Common.icon,
                    text: buttonText,
                    onAction: function() {
                        Ui.handleAction(editor);
                    },
                });
            };
        });
    };
});
